"""Property-based generators for consensus engine state spaces.

Implements generators for Raft-like consensus state, focusing on
invariant-preserving mutations and adversarial log configurations.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import IntEnum
from typing import Iterator, Sequence

from hypothesis import strategies as st
from hypothesis.strategies import SearchStrategy

from .primitives import node_id, term, entry_index


class NodeRole(IntEnum):
    FOLLOWER = 0
    CANDIDATE = 1
    LEADER = 2


@dataclass(frozen=True, slots=True)
class LogEntry:
    """A single consensus log entry with term and payload."""
    term: int
    index: int
    payload: bytes

    def __post_init__(self) -> None:
        if self.term < 0:
            raise ValueError(f"Term must be non-negative, got {self.term}")
        if self.index < 0:
            raise ValueError(f"Index must be non-negative, got {self.index}")


@dataclass(frozen=True, slots=True)
class NodeState:
    """Complete state of a single consensus node."""
    node_id: int
    role: NodeRole
    current_term: int
    voted_for: int | None
    log: tuple[LogEntry, ...]
    commit_index: int
    last_applied: int

    def __post_init__(self) -> None:
        if self.commit_index < 0:
            raise ValueError("commit_index must be non-negative")
        if self.last_applied < 0:
            raise ValueError("last_applied must be non-negative")
        if self.last_applied > self.commit_index:
            raise ValueError("last_applied cannot exceed commit_index")
        # Verify log ordering
        for prev, curr in zip(self.log, self.log[1:]):
            if prev.index >= curr.index:
                raise ValueError("Log indices must be strictly increasing")
            if prev.term > curr.term:
                raise ValueError("Terms must be non-decreasing along log")


@dataclass(frozen=True, slots=True)
class ClusterState:
    """A snapshot of the entire consensus cluster."""
    nodes: tuple[NodeState, ...]
    quorum_size: int

    def __post_init__(self) -> None:
        if self.quorum_size < 1:
            raise ValueError("quorum_size must be at least 1")
        if self.quorum_size > len(self.nodes):
            raise ValueError("quorum_size cannot exceed node count")
        # Quorum intersection property: 2*quorum_size > n
        if 2 * self.quorum_size <= len(self.nodes):
            raise ValueError(
                "Quorum intersection violated: 2*quorum_size must exceed node count"
            )


# --- Search Strategies ---

def log_entries(
    min_length: int = 0,
    max_length: int = 32,
    max_term: int = 16,
) -> SearchStrategy[tuple[LogEntry, ...]]:
    """Generate valid, ordered log entry sequences."""
    return (
        st.lists(
            st.builds(
                LogEntry,
                term=st.integers(min_value=0, max_value=max_term),
                index=st.integers(min_value=0, max_value=256),
                payload=st.binary(min_size=0, max_size=64),
            ),
            min_size=min_length,
            max_size=max_length,
        )
        .map(sorted, key=lambda e: e.index)
        .map(tuple)
        .filter(_is_valid_log)
    )


def _is_valid_log(entries: tuple[LogEntry, ...]) -> bool:
    """Ensure log maintains term non-decreasing invariant."""
    return all(
        prev.term <= curr.term
        for prev, curr in zip(entries, entries[1:])
    )


def node_state(
    node_id_val: int | None = None,
    log: tuple[LogEntry, ...] | None = None,
) -> SearchStrategy[NodeState]:
    """Generate a single node's state with consistent invariants."""
    return st.builds(
        NodeState,
        node_id=st.integers(min_value=0, max_value=1023) if node_id_val is None else st.just(node_id_val),
        role=st.sampled_from(list(NodeRole)),
        current_term=st.integers(min_value=0, max_value=32),
        voted_for=st.one_of(st.none(), st.integers(min_value=0, max_value=1023)),
        log=st.just(log) if log is not None else log_entries(),
        commit_index=st.integers(min_value=0, max_value=64),
        last_applied=st.integers(min_value=0, max_value=64),
    ).filter(_validate_node_state)


def _validate_node_state(state: NodeState) -> bool:
    """Filter to states satisfying internal consistency."""
    if state.commit_index > len(state.log):
        return False
    if state.last_applied > state.commit_index:
        return False
    # voted_for must be None or a valid node ID
    if state.voted_for is not None and state.voted_for < 0:
        return False
    return True


def cluster_state(
    min_nodes: int = 3,
    max_nodes: int = 9,
) -> SearchStrategy[ClusterState]:
    """Generate a cluster with guaranteed quorum intersection."""
    return (
        st.integers(min_value=min_nodes, max_value=max_nodes)
        .flatmap(lambda n: st.builds(
            ClusterState,
            nodes=st.lists(
                node_state(),
                min_size=n,
                max_size=n,
                unique_by=lambda s: s.node_id,
            ).map(tuple),
            quorum_size=st.integers(min_value=n // 2 + 1, max_value=n),
        ))
        .filter(lambda c: 2 * c.quorum_size > len(c.nodes))
    )


def adversarial_log() -> SearchStrategy[tuple[LogEntry, ...]]:
    """Generate logs designed to trigger edge cases in consensus.

    Produces logs with:
    - Duplicate indices (violating invariant)
    - Term regressions
    - Extremely large gaps between entries
    """
    return st.one_of(
        # Duplicate indices
        st.lists(
            st.builds(
                LogEntry,
                term=term(),
                index=st.integers(min_value=0, max_value=8),
                payload=st.binary(min_size=0, max_size=16),
            ),
            min_size=2,
            max_size=8,
        ).map(tuple),
        # Term regression
        st.builds(
            lambda t1, t2: (
                LogEntry(t1, 0, b"a"),
                LogEntry(t2, 1, b"b"),
            ),
            t1=st.integers(min_value=5, max_value=16),
            t2=st.integers(min_value=0, max_value=4),
        ),
        # Large index gaps
        st.builds(
            lambda i1, i2: (
                LogEntry(1, i1, b"a"),
                LogEntry(2, i2, b"b"),
            ),
            i1=st.integers(min_value=0, max_value=10),
            i2=st.integers(min_value=1000, max_value=10000),
        ),
    )


def divergent_cluster() -> SearchStrategy[ClusterState]:
    """Generate clusters where nodes have divergent logs.

    This is the primary stress test for consensus reconciliation.
    """
    return (
        st.integers(min_value=3, max_value=7)
        .flatmap(lambda n: st.builds(
            ClusterState,
            nodes=st.lists(
                st.builds(
                    NodeState,
                    node_id=node_id(),
                    role=st.just(NodeRole.FOLLOWER),
                    current_term=st.integers(min_value=0, max_value=8),
                    voted_for=st.none(),
                    log=st.one_of(
                        log_entries(max_length=16),
                        adversarial_log(),
                    ),
                    commit_index=st.integers(min_value=0, max_value=8),
                    last_applied=st.integers(min_value=0, max_value=8),
                ),
                min_size=n,
                max_size=n,
                unique_by=lambda s: s.node_id,
            ).map(tuple),
            quorum_size=st.integers(min_value=n // 2 + 1, max_value=n),
        ))
        .filter(lambda c: 2 * c.quorum_size > len(c.nodes))
    )


# --- Stateful Testing Support ---

class ConsensusStateMachine:
    """Hypothesis rule-based state machine for consensus testing."""

    def __init__(self, cluster: ClusterState) -> None:
        self.cluster = cluster
        self.current_term = max(n.current_term for n in cluster.nodes)
        self.leader_id: int | None = None
        self.votes_received: dict[int, set[int]] = {}
        self.committed_entries: list[LogEntry] = []

    @st.rule(
        candidate_id=st.integers(min_value=0, max_value=1023),
        term=st.integers(min_value=0, max_value=32),
    )
    def request_vote(self, candidate_id: int, term: int) -> None:
        """Simulate a RequestVote RPC."""
        if term < self.current_term:
            return  # Stale term, ignore
        if term > self.current_term:
            self.current_term = term
            self.votes_received[term] = set()
        if candidate_id not in self.votes_received[term]:
            self.votes_received[term].add(candidate_id)

    @st.rule(
        leader_id=st.integers(min_value=0, max_value=1023),
        prev_index=st.integers(min_value=0, max_value=64),
        prev_term=st.integers(min_value=0, max_value=32),
        entries=st.lists(
            st.builds(LogEntry, term=term(), index=entry_index(), payload=st.binary()),
            max_size=8,
        ),
    )
    def append_entries(
        self,
        leader_id: int,
        prev_index: int,
        prev_term: int,
        entries: list[LogEntry],
    ) -> None:
        """Simulate AppendEntries RPC."""
        self.leader_id = leader_id
        # Validate log matching property
        for entry in entries:
            if entry.index <= prev_index:
                continue  # Skip overlapping entries
            self.committed_entries.append(entry)

    @st.rule()
    def check_invariants(self) -> None:
        """Verify consensus invariants hold after operations."""
        # Term safety: committed entries at same index must have same term
        by_index: dict[int, set[int]] = {}
        for entry in self.committed_entries:
            by_index.setdefault(entry.index, set()).add(entry.term)
        for index, terms in by_index.items():
            assert len(terms) == 1, (
                f"Term safety violated at index {index}: terms {terms}"
            )

        # Leader completeness: committed entries must be contiguous
        indices = sorted(e.index for e in self.committed_entries)
        if indices:
            assert indices == list(range(indices[0], indices[-1] + 1)), (
                f"Non-contiguous committed entries: {indices}"
            )


consensus_state_machine = st.builds(ConsensusStateMachine, cluster=cluster_state())